import{_ as d,o as e,c as a,ag as o}from"./chunks/framework.C9sp7nFj.js";const p=JSON.parse('{"title":"ZONE","description":"","frontmatter":{},"headers":[],"relativePath":"2. 变量数据类型/3. 系统数据类型/ZONE.md","filePath":"2. 变量数据类型/3. 系统数据类型/ZONE.md","lastUpdated":1778862643000}'),r={name:"2. 变量数据类型/3. 系统数据类型/ZONE.md"};function n(s,t,c,_,i,l){return e(),a("div",null,[...t[0]||(t[0]=[o('<h1 id="zone" tabindex="-1">ZONE <a class="header-anchor" href="#zone" aria-label="Permalink to &quot;ZONE&quot;">​</a></h1><p>用于定义某一运动如何结束或者定义两条运动轨迹之间转弯区的大小。为了方便用户使用，系统预设了常用的过渡变量（系统变量，不允许用户修改），同时可支持用户自在全局，工程，程序三大变量作用域中对该变量进行创建，删除，修改等操作。</p><table tabindex="0"><thead><tr><th>参数</th><th>类型</th><th>说明</th><th>默认值/备注</th></tr></thead><tbody><tr><td><code>per</code></td><td>real</td><td>适用于 MovJ,MovJRel,MovJSearch 等关节运动指令，表示距离目标角度还有多远时开始转弯。</td><td>—</td></tr><tr><td><code>dis</code></td><td>real</td><td>用于 MovL,MovC 等直线圆弧运动指令，定义笛卡尔空间轨迹的转弯区大小，即当机器人运动到距离目标点还有 dis 毫米的地方时，开始转向往下一个目标点运动，单位是 mm。</td><td>—</td></tr><tr><td><code>vConst</code></td><td>int</td><td>过渡段线速度是否恒定不变的使能状态。为 1 表示过渡恒定不变，为 0 表示跟随过渡参数变化。 注：该参数一般在线速度不高的情况下使用，具体数值根据机器人类型会发生变化。</td><td>—</td></tr></tbody></table>',3)])])}const m=d(r,[["render",n]]);export{p as __pageData,m as default};
